import analysis

R = analysis.main()


def d(x, n=0):
    return f"{x:.{n}f}".replace(".", ",")


def pct(x):
    return f"{x * 100:.0f}%"


def rp(x):
    return f"{x:,.0f}".replace(",", ".")


G, P, TT = R["grid"], R["profiles"], R["two_tier"]
PARAMS = rp(R["model"]["params"])
MACS = d(R["model"]["macs"] / 1e6, 2)

